package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.ByteQuadsCanonicalizer;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class UTF8StreamJsonParser_getValueAsInt_TriageGen1Test {

    private IOContext ctxt;
    private ByteQuadsCanonicalizer sym;
    private byte[] inputBuffer;

    @Before
    public void setUp() {
        ctxt = IOContext.bootstrap();
        sym = ByteQuadsCanonicalizer.empty();
        inputBuffer = new byte[1024];
    }

    /**
     * Helper to instantiate the parser via reflection or constructor 
     * and manipulate private fields to simulate different internal states.
     */
    private UTF8StreamJsonParser createParser(String json, JsonToken token, int numTypesValid, int numberInt) throws Exception {
        InputStream is = new ByteArrayInputStream(json.getBytes());
        UTF8StreamJsonParser parser = new UTF8StreamJsonParser(
                ctxt, 0, is, null, sym, inputBuffer, 0, inputBuffer.length, false);

        setField(parser, "_currToken", token);
        setField(parser, "_numTypesValid", numTypesValid);
        setField(parser, "_numberInt", numberInt);

        return parser;
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetValueAsInt_WithIntToken_ValidType() throws Exception {
        // Case: (t == VALUE_NUMBER_INT) && (_numTypesValid & NR_INT) != 0
        // This skips the conversion logic and returns _numberInt directly
        UTF8StreamJsonParser parser = createParser("123", JsonToken.VALUE_NUMBER_INT, 1, 123); 

        int result = parser.getValueAsInt();
        assertEquals(123, result);
    }

    @Test
    public void testGetValueAsInt_WithFloatToken_ValidType() throws Exception {
        // Case: (t == VALUE_NUMBER_FLOAT) && (_numTypesValid & NR_INT) != 0
        UTF8StreamJsonParser parser = createParser("123.45", JsonToken.VALUE_NUMBER_FLOAT, 1, 123);

        int result = parser.getValueAsInt();
        assertEquals(123, result);
    }

    @Test
    public void testGetValueAsInt_WithIntToken_UnknownType_CallsParse() throws Exception {
        // Case: (t == VALUE_NUMBER_INT) && (_numTypesValid == NR_UNKNOWN)
        // NR_UNKNOWN is typically 0. We use a spy to intercept _parseIntValue
        UTF8StreamJsonParser realParser = createParser("123", JsonToken.VALUE_NUMBER_INT, 0, 0);
        UTF8StreamJsonParser parser = spy(realParser);

        doReturn(123).when(parser)._parseIntValue();

        int result = parser.getValueAsInt();
        assertEquals(123, result);
        verify(parser, times(1))._parseIntValue();
    }

    @Test
    public void testGetValueAsInt_WithIntToken_InvalidType_CallsConvert() throws Exception {
        // Case: (t == VALUE_NUMBER_INT) && (_numTypesValid & NR_INT) == 0 && (_numTypesValid != NR_UNKNOWN)
        // We simulate a state where NR_INT is not set, but it's not unknown (e.g., only NR_FLOAT is set)
        // Assuming NR_FLOAT = 2, NR_INT = 1. We set valid to 2.
        int NR_FLOAT = 2; 
        UTF8StreamJsonParser realParser = createParser("123", JsonToken.VALUE_NUMBER_INT, NR_FLOAT, 0);
        UTF8StreamJsonParser parser = spy(realParser);

        // When convertNumberToInt is called, it should update _numberInt
        doNothing().when(parser).convertNumberToInt();
        // Mock the internal update of _numberInt after conversion
        doAnswer(invocation -> {
            setField(parser, "_numberInt", 123);
            return null;
        }).when(parser).convertNumberToInt();

        int result = parser.getValueAsInt();
        assertEquals(123, result);
        verify(parser, times(1)).convertNumberToInt();
    }

    @Test
    public void testGetValueAsInt_WithNonNumberToken_CallsSuper() throws Exception {
        // Case: t is not VALUE_NUMBER_INT or VALUE_NUMBER_FLOAT
        // Should call super.getValueAsInt(0)
        // Since we cannot easily mock super, we test the behavior where it returns the default 0
        UTF8StreamJsonParser parser = createParser("\"string\"", JsonToken.VALUE_STRING, 1, 123);

        int result = parser.getValueAsInt();
        // Based on the logic, it falls through to super.getValueAsInt(0)
        // In a real scenario, super.getValueAsInt(0) for a string would return 0
        assertEquals(0, result);
    }

    @Test
    public void testGetValueAsInt_WithNullToken_CallsSuper() throws Exception {
        // Case: t is null
        UTF8StreamJsonParser parser = createParser("", null, 1, 123);

        int result = parser.getValueAsInt();
        assertEquals(0, result);
    }
}
